            return null;
        }

        var index = new Index(entityType, constraints);

        foreach (var (key, row) in rows)
        {
            index.Add(key, row);
        }

        return index;
    }

    /// <summary>The rows of one type indexed by their values on each declared UNIQUE constraint, applying the same comparison rules as <see cref="Verify"/>.</summary>
