        private readonly Type _entityType;
        private readonly IReadOnlyList<InMemoryUniqueConstraint> _constraints;
        private readonly Dictionary<object[], List<object>>[] _keysByValues;

        internal Index(Type entityType, IReadOnlyList<InMemoryUniqueConstraint> constraints)
        {
            _entityType = entityType;
            _constraints = constraints;
            _keysByValues = new Dictionary<object[], List<object>>[constraints.Count];

            for (var position = 0; position < constraints.Count; position++)
            {
                _keysByValues[position] = new Dictionary<object[], List<object>>(TupleComparer.Instance);
            }
        }

        /// <summary>Adds a row under its primary key (a tuple containing a null is not indexed, as it is not compared).</summary>
        public void Add(object key, EntityBaseCore row)
        {
            for (var position = 0; position < _constraints.Count; position++)
            {
                if (ValuesOf(row, _constraints[position]) is not { } values)
                {
                    continue;
                }

                if (!_keysByValues[position].TryGetValue(values, out var keys))
                {
                    keys = new List<object>(1);
                    _keysByValues[position].Add(values, keys);
                }

                keys.Add(key);
            }
        }

        /// <summary>Throws when a row other than the one under <paramref name="key"/> holds the same values as <paramref name="row"/> on a declared UNIQUE constraint.</summary>
        public void Verify(object key, EntityBaseCore row)
        {
            for (var position = 0; position < _constraints.Count; position++)
            {
                if (
                    ValuesOf(row, _constraints[position]) is { } values
                    && _keysByValues[position].TryGetValue(values, out var keys)
                    && keys.Exists(other => !InMemoryKeyComparer.KeysEqual(other, key))
                )
                {
                    throw DuplicateValueError(_entityType, _constraints[position], values);
                }
            }
        }
    }

    /// <summary>Compares member-value tuples the way <see cref="TupleEquals"/> does, with a hash code consistent with it.</summary>
    private sealed class TupleComparer : IEqualityComparer<object[]>
    {
        public static readonly TupleComparer Instance = new();

        public bool Equals(object[]? x, object[]? y) =>
            ReferenceEquals(x, y) || (x is not null && y is not null && TupleEquals(x, y));

        public int GetHashCode(object[] obj)
        {
            var hash = new HashCode();

            foreach (var value in obj)
            {
                hash.Add(StructuralComparisons.StructuralEqualityComparer.GetHashCode(value));
            }

            return hash.ToHashCode();
        }
    }

    /// <summary>Resolves the constraints declared on an entity type (a constraint naming a property the type does not have is dropped, as one whose columns cannot all be resolved is never generated).</summary>
    private static IReadOnlyList<InMemoryUniqueConstraint> Build(Type entityType)
    {
        var constraints = new List<InMemoryUniqueConstraint>();

        foreach (var attribute in entityType.GetCustomAttributes<UniqueConstraintAttribute>())
        {
            var properties = new List<PropertyInfo>(attribute.PropertyNames.Length);

            foreach (var propertyName in attribute.PropertyNames)
            {
                if (
                    entityType.GetProperty(
                        propertyName,
                        BindingFlags.Public | BindingFlags.Instance
                    )
                        is { } property
                )
                {
                    properties.Add(property);
                }
            }

            if (properties.Count > 0 && properties.Count == attribute.PropertyNames.Length)
            {
                constraints.Add(new InMemoryUniqueConstraint(attribute.Name, properties));
            }
        }

        return constraints;
    }
}

